"""
Commissioning
"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_factory import BtssmFactory
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from robot.libraries.BuiltIn import BuiltIn

logger = BackgroundLogger.Instance()


class Commissioning(object):
    """
    Commissioning
    """
    def __init__(self):
        self.oam_tool = BtssmFactory().get_instance().oam_tool

    def perform_commissioning(self, **kwargs):
        """
        Function to perform commissioning
        """
        file_path = kwargs.get("path")
        validate = kwargs.get("validate", False)
        timeout = kwargs.get("timeout", "15min")
        keepconn = kwargs.get("keepconn", None)
        wait_for_reset = kwargs.get("wait_for_reset", False)

        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["path", "validate", "timeout", "keepconn", "wait_for_reset"]}

        if not wait_for_reset:
            self.oam_tool.perform_full_commissioning(fullfile=file_path, validate=validate,
                                                     timeout=timeout,
                                                     keepconn=keepconn, **kwargs)
        else:
            self.oam_tool.perform_full_commissioning_and_wait_for_reset(fullfile=file_path,
                                                                        validate=validate,
                                                                        timeout=timeout,
                                                                        keepconn=keepconn,
                                                                        **kwargs)

    def _perform_delta_commissioning(self, **kwargs):
        param_file = kwargs.get("param_file")
        wait_for_reset = kwargs.get("wait_for_reset", False)
        keepconn = kwargs.get("keepconn", None)
        timeout = kwargs.get("timeout", "15min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["wait_for_reset", "param_file", "timeout", "keepconn"]}
        if not wait_for_reset:
            self.oam_tool.perform_parameter_file_commissioning(paramfile=param_file,
                                                               timeout=timeout,
                                                               keepconn=keepconn, **kwargs)
        elif wait_for_reset:
            self.oam_tool.perform_parameter_file_commissioning_and_wait_for_reset(
                paramfile=param_file, timeout=timeout, keepconn=keepconn, **kwargs)

    def _perform_parameter_commissioning(self, **kwargs):
        parameter = kwargs.get("parameter")
        wait_for_reset = kwargs.get("wait_for_reset", False)
        keepconn = kwargs.get("keepconn", None)
        timeout = kwargs.get("timeout", "15min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["wait_for_reset", "parameter", "timeout", "keepconn"]}
        if not wait_for_reset:
            self.oam_tool.perform_parameter_commissioning(paramfile=parameter, timeout=timeout,
                                                          keepconn=keepconn, **kwargs)
        elif wait_for_reset:
            self.oam_tool.perform_parameter_commissioning_and_wait_for_reset(paramfile=parameter,
                                                                             timeout=timeout,
                                                                             keepconn=keepconn,
                                                                             **kwargs)

    def perform_recommissioning(self, **kwargs):
        """
        Function to perform recommissioning
        """
        if kwargs.get("type").lower() == "delta":
            self._perform_delta_commissioning(**kwargs)
        elif kwargs.get("type").lower() == "param":
            self._perform_parameter_commissioning(**kwargs)
        else:
            BuiltIn.fail("Type not supported")
